window.kbPageData["views/entry/k-4e53e28a86df1a9c"] = {"key":"entry/k-4e53e28a86df1a9c","state":{"route":"entry/k-4e53e28a86df1a9c"},"node":{"id":"k-4e53e28a86df1a9c","mode":"k","title":"初次违法可以不予行政处罚的条件","type":"制度与规则","domain":"法律","reading":"","intro":"","priority":100,"aliases":[],"qs":["江苏 2024 B类 行测#9"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"依照《中华人民共和国行政处罚法》第三十三条第一款，初次违法且危害后果轻微并及时改正的，行政机关可以不予行政处罚。","review":{"definition":"依照《中华人民共和国行政处罚法》第三十三条第一款，初次违法且危害后果轻微并及时改正的，行政机关可以不予行政处罚。","explanation":"C项只给出“初次违法”，便得出“应免于处罚”，既遗漏了危害后果轻微和及时改正两个条件，也把“可以”改成了“应当”。同一款还规定，违法行为轻微并及时改正、没有造成危害后果的，不予行政处罚。","references":[],"evidence":"初次违法且危害后果轻微并及时改正的，可以不予行政处罚。","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"江苏 2024 B类 行测#9":{"paper":"江苏 2024 B类 行测","n":9,"mod":"常识判断","src":["0ae7ac475476e5635bd7.pdf",2],"asrc":["8dd171daee6fc74e9718.pdf",4],"card":"968e299dd64b8fead5bdeab6","links":[{"id":"k-4e53e28a86df1a9c","role":"解题依据","why":"行政处罚法将初次违法、危害后果轻微和及时改正共同列为可以不予处罚的条件。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-4e53e28a86df1a9c":[["江苏 2024 B类 行测#9"]]}};
